  ('ch2_KAL-001', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा राजस्थान के किस जिले में स्थित है?', 'हनुमानगढ़ जिले में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-001 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '0591d37165130f8a82b93e42547ad8b90078f4b99fc7ed7d15d61b2a4c47d1c2', NULL),
  ('ch2_KAL-002', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा किस नदी के बाएँ किनारे पर स्थित है?', 'वर्तमान में अधिकांशतः सूखी घग्घर नदी के बाएँ किनारे पर; गज़ेटियर इसे प्राचीन सरस्वती से जोड़ता है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-002 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'a5c98e07ddf99cd97cb817d57938f99f5f880ce8795f50b0bcc9aa7c51ad4984', NULL),
  ('ch2_KAL-003', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा हनुमानगढ़ जिले के किस ब्लॉक में स्थित है?', 'पीलीबंगा (Pilibangan) ब्लॉक में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-003 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'e9486de3fd3e8adfda83ca0c858be2d32c02ea01fd08981ccbc999bd024bbdae', NULL),
  ('ch2_KAL-004', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर में कालीबंगा के निर्देशांक क्या दिए गए हैं?', 'लगभग 29° 29′ उत्तरी अक्षांश और 74° 08′ पूर्वी देशांतर।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-004 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'ac67c354708dc8b84064516af26dccc212996d26326a9037fc05818d411e85bf', NULL),
  ('ch2_KAL-005', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा किस सभ्यता का प्रमुख पुरातात्त्विक स्थल है?', 'हड़प्पा / सिंधु सभ्यता का।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-005 — S4 — printed pp. 34–37; S1 — “Kalibangan” — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '28f436f5673758ec2df4bb9a0a74ffb996f28f910a323c051564b17ccd8426e7', NULL),
  ('ch2_KAL-006', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के पुरातात्त्विक स्थल पर किन दो सांस्कृतिक चरणों के प्रमाण मिले हैं?', 'प्रारम्भिक हड़प्पा (Early Harappan) और परिपक्व हड़प्पा (Mature Harappan) चरणों के।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-006 — S4 — printed pp. 36–37 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'aefece7d3ae699254599bfa700e44a84455ec3dafa95f02a31cc90401f7c900e', NULL),
