  ('ch2_KAL-008', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा-II (KLB-II) किस सांस्कृतिक चरण से संबंधित है?', 'हड़प्पा / Mature Harappan चरण से।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-008 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'bc56207ac176f64b4e72b3f1dd09de16ce4de27a8614964e74adef777bb7fed5', NULL),
  ('ch2_KAL-009', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर के अनुसार प्रारम्भिक हड़प्पा संस्कृति का अनुमानित काल कौन-सा है?', 'लगभग 3000–2700 ईसा पूर्व।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-009 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'b58ff6e7cddbe3c091736ea05d17422395cd4635225d589dbbd1f80eb65ad834', NULL),
  ('ch2_KAL-010', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर के अनुसार परिपक्व हड़प्पा संस्कृति का अनुमानित काल कौन-सा है?', 'लगभग 2600–1900 ईसा पूर्व।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-010 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '87c53065d2f85a32ad7e2b2b979de131706cd49ab74b044ef0fb7e7188a69885', NULL),
  ('ch2_KAL-011', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा की खोज/पहचान के इतिहास में 1952 में किसका नाम आता है?', 'श्री अमलानंद घोष ने 1952 में अपने exploration के दौरान इस स्थल को प्रमुखता से पहचाना (first highlighted)।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-011 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '2c379ce96b24fb465a40537631f38b110ad219ed5ee61505c7d807ce5e2fa20f', NULL),
  ('ch2_KAL-012', 'catalog.rajasthan_history_ancient_history_kalibangan', 'L. P. Tessitori ने कालीबंगा क्षेत्र का सर्वेक्षण किस अवधि में किया?', '1916–1919 के अपने राजपूताना सर्वेक्षण के दौरान; उन्होंने 1917 और 1918 में स्थल का दौरा किया।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-012 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '832fcade15b57861d3f8a3d55b85a52d75abe9df119e47739ea5edaed9df6e76', NULL),
  ('ch2_KAL-013', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा क्षेत्र का सर्वेक्षण करने वाले Aurel Stein ने यहाँ कब खोज/सर्वेक्षण किया?', 'दिसंबर 1941 में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-013 — S4 — printed pp. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '08e928a7d8d42aaa7645d1afde49e122c251a09a45a52be98ef14709f33b8dd3', NULL),
  ('ch2_KAL-014', 'catalog.rajasthan_history_ancient_history_kalibangan', 'जिला गज़ेटियर कालीबंगा का सबसे पुराना दर्ज लिखित उल्लेख किससे जोड़ता है?', 'James Tod से; गज़ेटियर इसे संभावित earliest recorded mention कहता है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-014 — S4 — printed p. 36; wording is qualified — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'cb8424989b6f060da95517d044976ed37b7e0e17f9e91ebdef5364d1ede48839', NULL),
  ('ch2_KAL-015', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का व्यवस्थित उत्खनन किस संस्था के अधीन हुआ?', 'भारतीय पुरातत्व सर्वेक्षण (Archaeological Survey of India — ASI) के अधीन।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-015 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '7a248b7c793f8ab27efbedff05d64143b1b1ab57382dccf074c2b2fe1fd4a1b9', NULL),
