  ('ch2_KAL-017', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा का उत्खनन कितने seasons में किया गया?', 'नौ seasons में।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-017 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '88e399427e6a59eba4744781f578486ffe8a8a5fe49596a72647d9265a6443d1', NULL),
  ('ch2_KAL-018', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा के उत्खनन से जुड़े प्रमुख पुरातत्वविद् कौन थे?', 'प्रो. B. B. Lal, B. K. Thapar और J. P. Joshi।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-018 — S4 — printed p. 34 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, 'c335832c255477784a0e6be3cc8800f3c2040295d641554ddf9623e169f33345', NULL),
  ('ch2_KAL-019', 'catalog.rajasthan_history_ancient_history_kalibangan', 'कालीबंगा स्थल पर कितने मुख्य numbered mounds (KLB-1, KLB-2, KLB-3) का वर्णन है?', 'तीन। इनके अतिरिक्त cemetery mound KLB-8 का भी उल्लेख है।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-019 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '3f18edc2877cfa23773acec6d5760a718b4ffeb7ec9b11fcfd616211f9c59bb9', NULL),
