  ('ch2_KAL-021', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-2 mound कहाँ स्थित था और किस चरण से संबंधित था?', 'बीच में स्थित सबसे बड़ा mound; Mature Harappan चरण से संबंधित।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-021 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '4cde44c5aa827ec8cf783ebce8912c2cd176980cb6d341e5ad846a8e42b6e701', NULL),
  ('ch2_KAL-022', 'catalog.rajasthan_history_ancient_history_kalibangan', 'KLB-3 mound कहाँ स्थित था और किस चरण से संबंधित था?', 'पूर्व में स्थित सबसे छोटा mound; Mature Harappan चरण से संबंधित।', 'hi', 'https://jankalyanfile.rajasthan.gov.in/Content/UploadFolder/DepartmentMaster/100/2023/Sep/30409/1002b8c1601-1f4b-47f8-95a7-c8eaebadc4a8.pdf', 'KAL-022 — S4 — printed p. 36 — स्वतंत्र स्रोत-समीक्षा लंबित।', 'NEEDS_REVIEW', 0.80, '9c063abf59df9775b8fd4d539db7b487ed6636fc97e02246c1a39a24eda10601', NULL),
